      var aiSuggestItems = [];
      var aiSuggestIndex = 0;
      var aiSuggestMode = null;
      var aiMentionFiles = [];
      var aiMentionBuildId = "";
      function closeAiSuggest() {
        aiSuggestMode = null;
        aiSuggestItems = [];
        document.getElementById("ai-suggest")?.classList.add("hidden");
      }
      function ensureAiSuggest() {
        let menu = document.getElementById("ai-suggest");
        if (menu)
          return menu;
        menu = document.createElement("div");
        menu.id = "ai-suggest";
        menu.className = "ai-suggest hidden";
        menu.addEventListener("click", (e) => {
          e.stopPropagation();
          const btn = e.target.closest("[data-suggest]");
          if (!btn?.dataset.suggest)
            return;
          void runAiSuggest(btn.dataset.suggest);
        });
        document.documentElement.appendChild(menu);
        return menu;
      }
      function tokenAtCursor(input) {
        const pos = input.selectionStart ?? input.value.length;
        const before = input.value.slice(0, pos);
        const slash = before.match(/(?:^|\s)\/([^\s]*)$/);
        if (slash)
          return { kind: "slash", query: slash[1] || "", start: pos - (slash[1] || "").length - 1 };
        const at = before.match(/(?:^|\s)@([^\s]*)$/);
        if (at)
          return { kind: "mention", query: at[1] || "", start: pos - (at[1] || "").length - 1 };
        return null;
      }
      function replaceActiveToken(text) {
        const input = document.getElementById("ai-input");
        if (!input)
          return;
        const mark = tokenAtCursor(input);
        if (!mark)
          return;
        const pos = input.selectionStart ?? input.value.length;
        input.value = `${input.value.slice(0, mark.start)}${text}${input.value.slice(pos)}`;
        const caret = mark.start + text.length;
        input.setSelectionRange(caret, caret);
        autoResizeAiInput();
      }
      function slashCommands() {
        return [
          { id: "slash:new", title: "\u041D\u043E\u0432\u044B\u0439 \u0447\u0430\u0442", hint: "/new" },
          { id: "slash:clear", title: "\u041E\u0447\u0438\u0441\u0442\u0438\u0442\u044C \u0447\u0430\u0442", hint: "/clear" },
          { id: "slash:folder", title: "\u041D\u043E\u0432\u0430\u044F \u043F\u0430\u043F\u043A\u0430", hint: "/folder" },
          { id: "slash:search", title: "\u041F\u043E\u0438\u0441\u043A \u043F\u043E \u0447\u0430\u0442\u0430\u043C", hint: "/search" },
          { id: "slash:telegram", title: "\u041F\u0440\u0438\u0432\u044F\u0437\u0430\u0442\u044C Telegram", hint: "/telegram" },
          { id: "slash:tools", title: "\u041F\u043E\u043A\u0430\u0437\u0430\u0442\u044C \u0438\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u044B", hint: "/tools" }
        ];
      }
      async function refreshMentionFiles(buildId) {
        if (!buildId || !api?.scanInstance) {
          aiMentionFiles = [];
          aiMentionBuildId = "";
          return;
        }
        if (aiMentionBuildId === buildId)
          return;
        aiMentionBuildId = buildId;
        try {
          const data = await api.scanInstance(buildId);
          aiMentionFiles = (data?.mods || []).slice(0, 24).map((m2) => {
            const filename = String(m2.filename || m2.file || m2.name || "");
            return { id: `file:${filename}`, title: String(m2.name || filename), hint: filename };
          }).filter((row) => row.hint);
        } catch {
          aiMentionFiles = [];
        }
        if (aiSuggestMode === "mention")
          syncAiSuggest();
      }
      function syncAiSuggest() {
        const input = document.getElementById("ai-input");
        if (!input)
          return;
        const token = tokenAtCursor(input);
        if (!token) {
          closeAiSuggest();
          return;
        }
        closeAiPopovers("ai-suggest");
        const q2 = token.query.toLowerCase();
        let items = [];
        if (token.kind === "slash") {
          items = slashCommands().filter((item) => !q2 || `${item.title} ${item.hint}`.toLowerCase().includes(q2));
        } else {
          const session = activeAiSession();
          const builds = savedBuilds.map((b2) => ({
            id: `build:${b2.id}`,
            title: b2.name,
            hint: [b2.gameVersion, b2.loader].filter(Boolean).join(" \xB7 ") || "\u0441\u0431\u043E\u0440\u043A\u0430"
          }));
          const current = session?.buildId ? builds.filter((b2) => b2.id === `build:${session.buildId}`) : [];
          items = [...current, ...builds.filter((b2) => !current.some((c) => c.id === b2.id)), ...aiMentionFiles];
          items = items.filter((item) => !q2 || `${item.title} ${item.hint}`.toLowerCase().includes(q2)).slice(0, 12);
          if (session?.buildId)
            void refreshMentionFiles(session.buildId);
        }
        aiSuggestMode = token.kind;
        aiSuggestItems = items;
        aiSuggestIndex = Math.max(0, Math.min(aiSuggestIndex, Math.max(0, items.length - 1)));
        const menu = ensureAiSuggest();
        if (!items.length) {
          menu.classList.add("hidden");
          return;
        }
        menu.innerHTML = items.map((item, i) => `<button type="button" class="ai-suggest__row${i === aiSuggestIndex ? " is-on" : ""}" data-suggest="${escapeAiHtml(item.id)}"><span>${escapeAiHtml(item.title)}</span><span class="ai-suggest__hint">${escapeAiHtml(item.hint)}</span></button>`).join("");
        menu.classList.remove("hidden");
        placeAiFloating(menu, input, "up");
      }
      function moveAiSuggest(delta) {
        if (!aiSuggestItems.length)
          return;
        aiSuggestIndex = (aiSuggestIndex + delta + aiSuggestItems.length) % aiSuggestItems.length;
        syncAiSuggest();
      }
